import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { intervalToExpireSchema, type IntervalToExpire } from "./interval-to-expire.js";
import { scopeInternalSchema, scopeSchema, type Scope } from "./scope.js";
import { typeSchema, type Type } from "./type.js";

export type Response = {
  /**
   * The access token that can be used to execute API actions. A unique identifier generated by
   * Global Payments to identify the merchant.
   */
  token?: string;
  /**
   * The type of token created.
   *   * `Bearer` - Indicates that the holder or bearer of this access token can access the API.
   */
  type?: Type;
  scope?: Scope;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** A meaningful label that better identifies the app. */
  appName?: string;
  /** Time indicating when the object was created in ISO-8601 format. Provided in UTC. */
  timeCreated?: string;
  /** The time in seconds that the access token will expire and can no longer be used. */
  secondsToExpire?: number;
  /**
   * The time interval set for when the token will expire.
   *   * `WEEK`
   *   * `DAY`
   *   * `12_HOURS`
   *   * `6_HOURS`
   *   * `3_HOURS`
   *   * `1_HOUR`
   *   * `30_MINUTES`
   *   * `10_MINUTES`
   *   * `5_MINUTES`
   */
  intervalToExpire?: IntervalToExpire;
  /** Email registered with the app that was used to create the access token */
  email?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const responseProperties: s.Shape<Response> = {
  token: s.optional(s.string()),
  type: s.optional(s.lazy(() => typeSchema)),
  scope: s.optional(s.lazy(() => scopeInternalSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  timeCreated: s.optional(s.string()),
  secondsToExpire: s.optional(s.float64()),
  intervalToExpire: s.optional(s.lazy(() => intervalToExpireSchema)),
  email: s.optional(s.string()),
  _keysMap: {
    appId: "app_id",
    appName: "app_name",
    timeCreated: "time_created",
    secondsToExpire: "seconds_to_expire",
    intervalToExpire: "interval_to_expire",
  },
};

export const responseInternalSchema: Schema<Response> = s.object<Response>(responseProperties, {
  additionalProperties: s.json(),
});

export const responseSchema: Schema<Response> = s.lazySchema(() =>
  s.object<Response>(
    {
      ...responseProperties,
      token: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      scope: s.optional(s.lazy(() => scopeSchema)),
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      email: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
